+#[test]
+fn the_angle_swings_about_the_landed_axis() {
+    let (world, mut h) = cyl_part([40.0, 0.0, 0.0]);
+    let plain = {
+        h.execute(&world, AlignPartToSetup::align_from_cylinder(&world, "Setup1", &wall(&world), TargetAxis::Z, 0.0, false).expect("align 0"));
