+    assert!((centre.pos.y - (-3.0)).abs() < TIGHT, "centre y: {}", centre.pos.y);
+    assert!((centre.pos.z - 7.0).abs() < TIGHT, "centre z: {}", centre.pos.z);
+    // Writing it through the command: the named setup's WCS lands
